INSERT INTO TBL_CHATBOT_TOPIC (TOPIC_ID, TITLE, INTRO, TOPIC_TYPE) VALUES (SEQ_CHATBOT_TOPIC.NEXTVAL, '영상 분석 견적', '집 안을 촬영한 영상을 올리면 AI가 가구와 짐의 부피를 분석해 예상 CBM과 견적을 계산해요.' || CHR(10) || '영상은 방 전체가 끊기지 않게 천천히 촬영하면 더 정확합니다.', '01');
INSERT INTO TBL_QUICK_MENU (MENU_ID, TOPIC_ID, MENU_NAME, SORT_ORDER) VALUES (SEQ_QUICK_MENU.NEXTVAL, SEQ_CHATBOT_TOPIC.CURRVAL, '영상 분석 견적', 3);
INSERT INTO TBL_LOREBOOK (LOREBOOK_ID, TOPIC_ID, KEYWORDS, CONTENT, SORT_ORDER) VALUES (SEQ_LOREBOOK.NEXTVAL, SEQ_CHATBOT_TOPIC.CURRVAL, '#영상#촬영#CBM#분석', '방마다 문을 열고 천천히 한 바퀴 돌며 촬영해 주세요. 가구 뒤나 붙박이장 안처럼 짐이 있는 곳도 함께 찍으면 더 정확합니다.', 1);
INSERT INTO TBL_CHATBOT_ACTION (ACTION_ID, TOPIC_ID, LABEL, ACTION_TYPE, ACTION_VALUE, SORT_ORDER) VALUES (SEQ_CHATBOT_ACTION.NEXTVAL, SEQ_CHATBOT_TOPIC.CURRVAL, '영상 견적 시작', '01', '/quote', 1);
INSERT INTO TBL_CHATBOT_ACTION (ACTION_ID, TOPIC_ID, LABEL, ACTION_TYPE, ACTION_VALUE, SORT_ORDER) VALUES (SEQ_CHATBOT_ACTION.NEXTVAL, SEQ_CHATBOT_TOPIC.CURRVAL, '촬영 방법 보기', '02', '영상을 어떻게 촬영해야 하나요?', 2);
INSERT INTO TBL_CHATBOT_TOPIC (TOPIC_ID, TITLE, INTRO, TOPIC_TYPE) VALUES (SEQ_CHATBOT_TOPIC.NEXTVAL, '이사 준비', '이사 전에는 귀중품 별도 보관, 냉장고 음식 정리, 주소 이전, 가전 설치 일정을 먼저 확인해주세요.' || CHR(10) || '이사 전날에는 주차 공간과 엘리베이터 예약도 확인하는 것이 좋아요.', '01');
INSERT INTO TBL_QUICK_MENU (MENU_ID, TOPIC_ID, MENU_NAME, SORT_ORDER) VALUES (SEQ_QUICK_MENU.NEXTVAL, SEQ_CHATBOT_TOPIC.CURRVAL, '이사 준비 체크리스트', 4);
INSERT INTO TBL_LOREBOOK (LOREBOOK_ID, TOPIC_ID, KEYWORDS, CONTENT, SORT_ORDER) VALUES (SEQ_LOREBOOK.NEXTVAL, SEQ_CHATBOT_TOPIC.CURRVAL, '#당일#준비물#귀중품', '귀중품과 중요 서류는 직접 챙겨 주시고, 냉장고는 전날 미리 비워 두시면 좋습니다.', 1);
INSERT INTO TBL_CHATBOT_TOPIC (TOPIC_ID, TITLE, INTRO, TOPIC_TYPE) VALUES (SEQ_CHATBOT_TOPIC.NEXTVAL, '결제 · 환불', '견적을 확정하면 바로 예약이 확정되고, 계약금은 결제 대기 상태로 안내돼요.' || CHR(10) || '취소·환불 가능 금액은 작업일과 취소 시점에 따라 달라질 수 있어 상담사 확인이 필요합니다.', '01');
INSERT INTO TBL_QUICK_MENU (MENU_ID, TOPIC_ID, MENU_NAME, SORT_ORDER) VALUES (SEQ_QUICK_MENU.NEXTVAL, SEQ_CHATBOT_TOPIC.CURRVAL, '결제 및 환불 문의', 5);
INSERT INTO TBL_LOREBOOK (LOREBOOK_ID, TOPIC_ID, KEYWORDS, CONTENT, SORT_ORDER) VALUES (SEQ_LOREBOOK.NEXTVAL, SEQ_CHATBOT_TOPIC.CURRVAL, '#결제#환불#계약금#취소', '안내된 계약금을 결제하면 결제가 완료됩니다. 취소·환불 기준은 작업일과 취소 시점에 따라 달라 상담사가 확인해 드립니다.', 1);
INSERT INTO TBL_CHATBOT_ACTION (ACTION_ID, TOPIC_ID, LABEL, ACTION_TYPE, ACTION_VALUE, SORT_ORDER) VALUES (SEQ_CHATBOT_ACTION.NEXTVAL, SEQ_CHATBOT_TOPIC.CURRVAL, '상담사에게 문의', '03', NULL, 1);
INSERT INTO TBL_CHATBOT_TOPIC (TOPIC_ID, TITLE, INTRO, TOPIC_TYPE) VALUES (SEQ_CHATBOT_TOPIC.NEXTVAL, '사다리차 이용', '사다리차 필요 여부와 추가 비용을 안내합니다.', '01');
INSERT INTO TBL_LOREBOOK (LOREBOOK_ID, TOPIC_ID, KEYWORDS, CONTENT, SORT_ORDER) VALUES (SEQ_LOREBOOK.NEXTVAL, SEQ_CHATBOT_TOPIC.CURRVAL, '#사다리차#엘리베이터#고층', '현장 층수와 작업 환경에 따라 사다리차 필요 여부 및 비용이 달라집니다. 현장 확인 후 정확한 금액을 안내해 드립니다.', 1);
INSERT INTO TBL_SAVED_REPLY (REPLY_ID, TITLE, CONTENT) VALUES (SEQ_SAVED_REPLY.NEXTVAL, '방문 견적 안내', '방문 견적은 담당자가 현장을 확인한 뒤 확정 금액을 안내해 드립니다. 원하시는 방문 날짜와 시간을 알려주세요.');
INSERT INTO TBL_SAVED_REPLY (REPLY_ID, TITLE, CONTENT) VALUES (SEQ_SAVED_REPLY.NEXTVAL, '사다리차 비용 안내', '사다리차 비용은 층수와 작업 환경에 따라 달라집니다. 현장 확인 후 정확한 금액을 안내해 드리겠습니다.');
INSERT INTO TBL_SAVED_REPLY (REPLY_ID, TITLE, CONTENT) VALUES (SEQ_SAVED_REPLY.NEXTVAL, '상담 종료 인사', '문의해 주셔서 감사합니다. 더 궁금한 점이 있으시면 언제든 채팅으로 남겨 주세요.');
